import { tags } from "typia";

/**
 * Pagination metadata providing information about the current page position and total data available. This type is returned with all paginated list responses to enable frontend components to render navigation controls, page numbers, and "Showing X of Y" indicators.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPagination = {
  /**
   * Current page number (1-based index). Indicates which page of results the client is currently viewing.
   *
   * @x-autobe-specification Current page number from request. Default: 1, minimum: 1. Extracted from IPage.IRequest.page parameter.
   */
  page: number & tags.Type<"int32"> & tags.Minimum<1>;

  /**
   * Number of items per page. Maximum value is 20 items per page as enforced by business rules for product listings, category listings, wishlists, and order history.
   *
   * @x-autobe-specification Items per page from request. Default: 10, range: 1-20 per business rules section [1251]. Extracted from IPage.IRequest.limit parameter. Enforced by service layer per business rules.
   */
  limit: number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<20>;

  /**
   * Total number of items matching the query across all pages. Represents the complete result set count.
   *
   * @x-autobe-specification Computed COUNT(*) from database query matching all filters. Represents total records in result set before pagination. Calculated by service layer during list operation.
   */
  totalItems: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total number of pages available. Calculated as ceiling(totalItems / limit). Zero when there are no items.
   *
   * @x-autobe-specification Calculated as CEIL(totalItems / limit) by service layer. Zero when totalItems=0. Derived value, not stored in database.
   */
  totalPages: number & tags.Type<"int32"> & tags.Minimum<0>;
};
